package com.ray.controller;import com.ray.dto.CommissionRuleUpdateDTO;import com.ray.result.*;import com.ray.service.FinanceService;import com.ray.vo.*;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;
@RestController @SecurityRequirement(name="BearerAuth") @Tag(name="佣金与资金账本") public class FinanceController {private final FinanceService s;public FinanceController(FinanceService s){this.s=s;}@GetMapping("/v1/admin/commission-rules")@Operation(summary="查询佣金规则",operationId="getCommissionRule")public Result<CommissionRuleVO> rule(@RequestParam(required=false)String shopId){return Result.ok(s.rule(shopId));}@PutMapping("/v1/admin/commission-rules")@Operation(summary="更新佣金规则",operationId="updateCommissionRule")public Result<CommissionRuleVO> update(@RequestParam(required=false)String shopId,@Valid @RequestBody CommissionRuleUpdateDTO r,@RequestHeader("Idempotency-Key") @Pattern(regexp="[A-Za-z0-9._:-]{8,128}")String key){return Result.ok(s.update(shopId,r,key));}@GetMapping("/v1/admin/ledger-entries")@Operation(summary="查询资金账本",operationId="listLedgerEntries")public Result<PageResult<FundLedgerEntryVO>> ledger(@RequestParam(defaultValue="1")@Min(1)int page,@RequestParam(defaultValue="20")@Min(1)@Max(100)int size){return Result.ok(s.ledger(page,size));}@GetMapping("/v1/merchant/finance/summary")@Operation(summary="查询商户财务摘要",operationId="getMerchantFinanceSummary")public Result<MerchantFinanceSummaryVO> summary(){return Result.ok(s.merchantSummary());}}
